 // La comprobación solo acredita el origen actual; no certifica otros equipos.\n  if(!document.getElementById('queue-review5d').checked)throw Error('OTHER_ORIGINS_REVIEW_REQUIRED');\n}\n\n// Solo suspende consultas automáticas; no modifica colas, recibos ni confirmaciones.\nfunction startLabPolling({sync,allowed,documentRef=document,windowRef=window,navigatorRef=navigator,setIntervalFn=setInterval,clearIntervalFn=clearInterval}){\n let running=false,stopped=false;\n const tick=async()=>{if(stopped||running||documentRef.visibilityState!=='visible'||navigatorRef.onLine===false||!allowed())return;running=true;try{await sync();}finally{running=false;}};\n const onVisible=()=>{if(documentRef.visibilityState==='visible')void tick();};\n const onOnline=()=>void tick();\n const timer=setIntervalFn(()=>void tick(),120000);\n documentRef.addEventListener('visibilitychange',onVisible);windowRef.addEventListener('online',onOnline);\n return ()=>{stopped=true;clearIntervalFn(timer);documentRef.removeEventListener('visibilitychange',onVisible);windowRef.removeEventListener('online',onOnline);};\n}\n\n// Cola separada para permisos: conserva el ID aun si se pierde la respuesta.\nasync function adminMutation({store,actor,payload,send,uuid=()=>crypto.randomUUID()}){\n  let command;\n  await store.transact(s=>{\n    s.adminQueue5d=s.adminQueue5d||[];\n    const old=s.adminQueue5d.find(x=>x.command.subject===payload.subject);\n    if(old){if(old.actor!==actor||old.command.role!==payload.role||old.command.active!==payload.active)throw Error('ADMIN_PENDING_RECOVERY_REQUIRED');command=old.command;}\n    else{command={...payload,operationId:'admin-'+uuid()};s.adminQueue5d.push({actor,command});}\n  });\n  const result=await send(command);\n  if(result?.state!=='COMMITTED'||result.operationId!==command.operationId||!Number.isSafeInteger(result.revision))throw Error('ADMIN_NOT_CONFIRMED');\n  await store.transact(s=>{s.adminReceipts5d=s.adminReceipts5d||{};s.adminReceipts5d[command.operati